// keystone.ts → server.extendExpressApp
app.get('/api/lumina/charts', async (request, response) => {
  requireSecret(request)
  const context = (await commonContext.withRequest(request, response)).sudo()

  const [lessons, components] = await Promise.all([
    context.query.Lesson.findMany({ query: 'track published' }),
    context.query.Component.findMany({
      query: 'kind status surface createdAt'
    })
  ])

  const byTrack = new Map()
  for (const lesson of lessons) {
    const track = lesson.track ?? 'foundations'
    byTrack.set(track, (byTrack.get(track) ?? 0) + 1)
  }

  const byStatus = new Map()
  for (const component of components) {
    byStatus.set(component.status, (byStatus.get(component.status) ?? 0) + 1)
  }

  // The browser receives counts only: no names, code, or owner sessions.
  response.json({
    data: {
      lessonsByTrack: [...byTrack].map(([name, value]) => ({ name, value })),
      componentsByStatus: [...byStatus].map(([name, value]) => ({ name, value }))
    }
  })
})
